style.css:
@-moz-document domain("character.ai") {
/* ? FONDO */
body {
    background-image: url("https://i.pinimg.com/1200x/2a/12/23/2a1223624f525939caee294b6c256f53.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;

    font-family: "Quicksand", "Segoe UI", sans-serif !important;

    color: #000000 !important; /* ? TEXTO NEGRO GLOBAL */
}

/* ?️ OVERLAY */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(234, 246, 255, 0.35) !important;
    pointer-events: none !important;
}

/* ? BURBUJAS BOT */
div[class*="messageContent"],
div[class*="prose"],
div[class*="markdown"] {
    background: #FFC0CB !important;
    border: 5px solid #FFFACD !important;
    border-radius: 18px !important;
    padding: 8px 10px !important;

    color: #000000 !important; /* ? TEXTO NEGRO */
}

/* ? TEXTO INTERNO FORZADO */
div[class*="messageContent"] *,
div[class*="prose"] *,
div[class*="markdown"] * {
    color: #000000 !important;
}

/* ? USUARIO */
div[class*="user"] {
    background: #ff9fb2 !important;
    border: 5px solid #FFFACD !important;
    border-radius: 18px !important;

    color: #000000 !important;
}

/* ? LIMPIEZA DE FONDOS RAROS */
div,
section,
main,
aside {
    background-color: transparent !important;
}

/* ? BOTONES */
button,
[role="button"],
div[role="button"],
a[role="button"],
div[class*="cursor-pointer"],
div[class*="Button"],
div[class*="button"] {
    background: #ffe1ea !important;
    border-radius: 12px !important;
    border: none !important;

    color: #000000 !important;
}

/* ? ICONOS */
button svg,
[role="button"] svg,
div[role="button"] svg {
    fill: #000000 !important;
}

/* ✍️ INPUT */
textarea {
    background: #EAF6FF !important;
    border-radius: 14px !important;
    border: 1px solid #cfe9ff !important;
    font-size: 14px !important;

    color: #000000 !important;
}

/* ? HEADER */
header, nav {
    background: rgba(234, 246, 255, 0.85) !important;
    backdrop-filter: blur(8px);
}

/* ? LINKS (ANTES AZULES → AHORA NEGROS) */
a {
    color: #000000 !important;
}

/* ✨ HOVER */
button:hover,
[role="button"]:hover,
div[class*="cursor-pointer"]:hover {
    background: #ffc9d6 !important;
}
}
